1	import assert from "node:assert/strict";
2	import { createServer } from "node:http";
3	import type { AddressInfo } from "node:net";
4	import { after, test } from "node:test";
5	import { handle } from "../src/server.ts";
6	
7	const server = createServer(handle).listen(0);
8	const base = `http://localhost:${(server.address() as AddressInfo).port}`;
9	after(() => server.close());
10	
11	test("POST then GET /api/todos", async () => {
12	  const created = await fetch(`${base}/api/todos`, {
13	    method: "POST",
14	    body: JSON.stringify({ title: "Write tests" }),
15	  });
16	  assert.equal(created.status, 201);
17	  const todos = await (await fetch(`${base}/api/todos`)).json();
18	  assert.equal(todos.at(-1).title, "Write tests");
19	});
20	
21	test("POST with a dueDate returns it, and GET keeps it", async () => {
22	  const res = await fetch(`${base}/api/todos`, {
23	    method: "POST",
24	    body: JSON.stringify({ title: "Pay rent", dueDate: "2026-12-31" }),
25	  });
26	  assert.equal(res.status, 201);
27	  assert.equal((await res.json()).dueDate, "2026-12-31");
28	  const todos = await (await fetch(`${base}/api/todos`)).json();
29	  assert.equal(todos.at(-1).dueDate, "2026-12-31");
30	});
31	
32	test("POST without a dueDate (or null) gives dueDate null", async () => {
33	  for (const body of [{ title: "a" }, { title: "b", dueDate: null }]) {
34	    const res = await fetch(`${base}/api/todos`, { method: "POST", body: JSON.stringify(body) });
35	    assert.equal(res.status, 201);
36	    const todo = await res.json();
37	    assert.equal(todo.dueDate, null);
38	    const toggled = await (await fetch(`${base}/api/todos/${todo.id}`, { method: "PATCH" })).json();
39	    assert.ok("dueDate" in toggled);
40	  }
41	});
42	
43	test("POST with a bad dueDate is a 400", async () => {
44	  const bad = ["31/12/2026", "2026-1-5", 20261231, "2026-12-31T10:00", "2026-02-30", "2026-13-01", ""];
45	  for (const dueDate of bad) {
46	    const res = await fetch(`${base}/api/todos`, {
47	      method: "POST",
48	      body: JSON.stringify({ title: "x", dueDate }),
49	    });
50	    assert.equal(res.status, 400, `dueDate ${JSON.stringify(dueDate)}`);
51	  }
52	});
53	
54	test("POST /api/todos without a title is a 400", async () => {
55	  const res = await fetch(`${base}/api/todos`, { method: "POST", body: "{}" });
56	  assert.equal(res.status, 400);
57	});
